export function* parentChain<T>(
  start: number,
  read: (current: number) => { data: T; parent: ParentIssue },
  maxHops: number = MAX_PARENT_HOPS,
): Generator<ParentHop<T>> {
  const visited = new Set<number>();
  let current = start;
  for (let hop = 0; hop < maxHops; hop++) {
