  /** Every `gh` invocation made so far, anywhere in the process tree, in order. */
  calls(): string[][];
}

export function setupFakeGh(rules: FakeGhRule[]): FakeGh {
  const dir = mkdtempSync(join(tmpdir(), "atomaton-e2e-fakegh-"));
