+    expect(r.branch).toBe("");
+    expect(r.stderr).toContain("staying on the base branch");
+  });
+
+  test("an issue with no branch of its own starts on the base", () => {
+    const r = run([{ match: ["matching-refs"], stdout: "[]" }]);
+    expect(r.status).toBe(0);
+    expect(r.branch).toBe("");
+  });
